<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';wajib_role(['ADMIN']);if($_SERVER['REQUEST_METHOD']!=='POST')redirect_to('pengguna.php');csrf_verify();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if($id===(int)$_SESSION['id_pengguna']){flash('error','Akun yang sedang digunakan tidak boleh dihapus.');redirect_to('pengguna.php');}$st=mysqli_prepare($koneksi,"SELECT * FROM pengguna WHERE id_pengguna=?");mysqli_stmt_bind_param($st,'i',$id);mysqli_stmt_execute($st);$old=mysqli_fetch_assoc(mysqli_stmt_get_result($st));mysqli_stmt_close($st);if(!$old)redirect_to('pengguna.php');$st=mysqli_prepare($koneksi,"DELETE FROM pengguna WHERE id_pengguna=?");mysqli_stmt_bind_param($st,'i',$id);if(mysqli_stmt_execute($st)){audit_log($koneksi,(int)$_SESSION['id_pengguna'],'pengguna',(string)$id,'DELETE',$old,null);flash('success','Pengguna berhasil dihapus.');}else flash('error','Pengguna tidak dapat dihapus karena masih memiliki data terkait.');redirect_to('pengguna.php');